// Construye el batchUpdate de estructura.
// SOLO agrega pestanas nuevas. Nunca borra ni toca Sheet1 ni Gastos.

const HOJAS = [
  'Configuracion', 'Categorias', 'GastosFijos', 'Transacciones',
  'Ingresos', 'Resumen', 'Alertas', 'Pendientes', 'Auditoria'
];

const existentes = new Set(
  ($json.sheets || []).map(s => s.properties.title)
);

const faltantes = HOJAS.filter(h => !existentes.has(h));

const requests = [];
for (const titulo of faltantes) {
  requests.push({
    addSheet: {
      properties: {
        title: titulo,
        gridProperties: { rowCount: 2000, columnCount: 32, frozenRowCount: 1 }
      }
    }
  });
}

return [{
  json: {
    faltantes,
    ya_existian: [...existentes],
    hay_trabajo: requests.length > 0,
    body: { requests }
  }
}];

// Reporte de lo que se hizo, para verificar sin abrir el Sheet.
const pestanas = $('Calcular Pestanas Faltantes').first().json;
const datos = $('Construir Datos').first().json;
const resp = $json;

return [{
  json: {
    ok: true,
    pestanas_creadas: pestanas.faltantes,
    pestanas_ya_existian: pestanas.ya_existian,
    celdas_actualizadas: resp.totalUpdatedCells || null,
    rangos_actualizados: resp.totalUpdatedSheets || null,
    control: datos.control
  }
}];
